    [2032]={name="Gallan Cuffs",quality=2,ilvl=36,reqLevel=27,sourceType="quest_reward",instructions="Reward from the quest 'To Steal From Thieves'. Pick it over the other reward choices. Starts with Genavie Callow in Undercity. Objective: Bring Kenata, Fardel, and Marcel Dabyrie's Heads to Genavie Callow in Undercity.",zone="Undercity",questName="To Steal From Thieves",lore="The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed! My family is gone, taken by the plague."},
    [2033]={name="Ambassador's Boots",quality=3,ilvl=25,reqLevel=22,sourceType="quest_reward",instructions="Reward from the quest 'Crime and Punishment'. Pick it over the other reward choices. Starts with Councilman Millstipe in Duskwood. Objective: Councilman Millstipe of Darkshire wants you to bring him the hand of Dextren Ward.",zone="The Stockade",questName="Crime and Punishment"},
    [2036]={name="Dusty Mining Gloves",quality=2,ilvl=18,reqLevel=14,sourceType="quest_reward",instructions="Reward from the quest 'Collecting Memories'. Pick it over the other reward choices. Starts with Wilder Thistlenettle in Stormwind City. Objective: Retrieve 4 Miners' Union Cards and return them to Wilder Thistlenettle in Stormwind.",zone="The Deadmines",questName="Collecting Memories",lore="Many of my friends perished that horrible day when the mine tunnel caved in. If your adventures happen to bring you into that wing of the mine in Moonbrook, please keep an eye out for any sign which might identify them."},
    [2039]={name="Plains Ring",quality=3,ilvl=29,reqLevel=24,sourceType="world_drop",instructions="World drop around level 24-27."},
    [2041]={name="Tunic of Westfall",quality=3,ilvl=24,reqLevel=14,sourceType="quest_reward",instructions="Reward from the quest 'The Defias Brotherhood'. Pick it over the other reward choices.",zone="The Deadmines",questName="The Defias Brotherhood",lore="Edwin VanCleef must be assassinated. While it saddens me to condemn any man to a death sentence, it is for the greater good of the people of Westfall that VanCleef is laid to rest once and for all."},
    [2044]={name="Crescent of Forlorn Spirits",quality=2,ilvl=35,reqLevel=22,sourceType="quest_reward",instructions="Reward from the quest 'The Legend of Stalvan'. Pick it over the other reward choices. Starts with Commander Althea Ebonlocke in Duskwood. Objective: Kill Stalvan Mistmantle and show Madame Eva his family ring.",zone="Duskwood",questName="The Legend of Stalvan",lore="Stalvan Mistmantle led a life of depravity. Innocent victims died by his hand. Undoubtedly he is guilty of countless crimes. Now the lunatic threatens Darkshire."},
