    [4454]={name="Talon of Vultros",quality=3,ilvl=28,reqLevel=23,sourceType="world_drop",instructions="Drops from Vultros (rare spawn).",zone="Sentinel Hill",npc="Vultros"},
    [4462]={name="Cloak of Rot",quality=2,ilvl=33,reqLevel=28,sourceType="world_drop",instructions="Drops from Lord Malathrom (rare spawn).",zone="Raven Hill",npc="Lord Malathrom"},
    [4474]={name="Ravenwood Bow",quality=2,ilvl=32,reqLevel=27,sourceType="world_drop",instructions="Drops from Fenros (rare spawn).",zone="Twilight Grove",npc="Fenros"},
    [4504]={name="Dwarven Guard Cloak",quality=2,ilvl=31,reqLevel=28,sourceType="quest_reward",instructions="Reward from the quest 'The Thandol Span'. Pick it over the other reward choices. Starts with Rhag Garmason in Arathi Highlands. Objective: Rhag Garmason wants you to locate Ol' Rustlocke.",zone="Wetlands",questName="The Thandol Span",lore="Heavens no! Poor Rustlocke. 'Tis quite a tragedy indeed. We must not let his death pass in vain."},
    [4535]={name="Ironforge Memorial Ring",quality=2,ilvl=31,reqLevel=25,sourceType="quest_reward",instructions="Reward from the quest 'A King's Tribute'. Starts with Grand Mason Marblesten in Ironforge. Objective: Report to King Magni Bronzebeard.",zone="Ironforge",questName="A King's Tribute",lore="Such a shame the land is in such shambles. But the Memorial came out quite well!"},
    [4543]={name="White Drakeskin Cap",quality=2,ilvl=40,reqLevel=35,sourceType="quest_reward",instructions="Reward from the quest 'Foul Magics'. Pick it over the other reward choices. Starts with Tor'gan in Arathi Highlands. Objective: Retrieve Marez Cowl's Bloodstone Orb and bring it to Tor'gan in Hammerfall.",zone="Arathi Highlands",questName="Foul Magics",lore="There is no doubt in my mind that a powerful warlock resides within the walls of Stromgarde. From time to time, using an arcane magical relic, this warlock has summoned forth terrible demons in large numbers."},
    [4549]={name="Seafire Band",quality=2,ilvl=46,reqLevel=35,sourceType="quest_reward",instructions="Reward from the quest 'Death From Below'. Pick it over the other reward choices.",zone="Arathi Highlands",questName="Death From Below",lore="This is bad. It seems the Daggerspines are amassing for an attack. Naga are known for their ruthlessness in battle. They will keep attacking until I am dead."},
