    [5781]={name="Murloc Scale Breastplate",quality=2,ilvl=19,reqLevel=14,sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [5783]={name="Murloc Scale Bracers",quality=2,ilvl=38,reqLevel=33,sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [5813]={name="Emil's Brand",quality=2,ilvl=32,reqLevel=24,sourceType="quest_reward",instructions="Reward from the quest 'Insane Druids'. Starts with Kayneth Stillwind in Ashenvale. Objective: Kill the druids: Taneel Darkwood, Uthil Mooncall, Mavoris Cloudsbreak; then return to Kayneth Stillwind in Forest Song.",zone="Ashenvale",questName="Insane Druids",lore="When I struggled with the Forsaken's poisons, I had a vision. I had a vision of the druids in the Dor'danil Barrow Den, poisoned... murdered by the undead!"},
    [5817]={name="Lunaris Bow",quality=2,ilvl=30,reqLevel=25,sourceType="quest_reward",instructions="Reward from the quest 'Answered Questions'. Pick it over the other reward choices. Starts with Jonathan Carevin in Darnassus. Objective: Return to Thyn'tel Bladeweaver in Darnassus.",zone="Ashenvale",questName="Answered Questions",lore="We shall rein in the worgen problem, have no worry of that. This evil that your friend introduced to our woods will be contained, and I bear her no ill will for her actions."},
    [5820]={name="Faerie Mantle",quality=2,ilvl=32,reqLevel=26,sourceType="quest_reward",instructions="Reward from the quest 'The Branch of Cenarius'. Pick it over the other reward choices. Starts with Anilia in Ashenvale. Objective: Kill Geltharis and return the Branch of Cenarius to Illiyana at the Shrine of Aessina.",zone="Ashenvale",questName="The Branch of Cenarius",lore="Anilia puts her hands on your shoulders and draws you close. Gasping, she points towards the arch to the north, before her eyes close and her last wheezing breath leaves her body."},
    [5957]={name="Handstitched Leather Vest",quality=2,ilvl=8,reqLevel=3,sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [5958]={name="Fine Leather Pants",quality=2,ilvl=21,reqLevel=16,sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
