    [6469]={name="Venomstrike",quality=3,ilvl=24,reqLevel=19,sourceType="boss_drop",instructions="Drops from Lord Serpentis.",zone="Wailing Caverns",npc="Lord Serpentis",proc="Equip: Chance to strike your ranged target with a Venom Shot for 31 to 45 Nature damage."},
    [6477]={name="Grassland Sash",quality=2,ilvl=20,reqLevel=14,sourceType="quest_reward",instructions="Reward from the quest 'Consumed by Hatred'. Pick it over the other reward choices. Starts with Mankrik in The Barrens. Objective: Bring 60 Bristleback Quilboar Tusks to Mankrik at the Crossroads.",zone="The Barrens",questName="Consumed by Hatred",lore="Perhaps you know the pain of uncertainty, perhaps not. But know this: I stand here every day, from the sun's rising till its decline, scouring the horizon for more of those monsters."},
    [6480]={name="Slick Deviate Leggings",quality=2,ilvl=20,reqLevel=13,sourceType="quest_reward",instructions="Reward from the quest 'Deviate Hides'. Pick it over the other reward choices.",zone="Wailing Caverns",questName="Deviate Hides",lore="These deviate creatures have strange, otherworldly properties."},
    [6504]={name="Wingblade",quality=3,ilvl=24,reqLevel=10,sourceType="quest_reward",instructions="Reward from the quest 'Leaders of the Fang'. Pick it over the other reward choices. Starts with Nara Wildmane in Thunder Bluff. Objective: Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff.",zone="Wailing Caverns",questName="Leaders of the Fang",lore="The druids in the Wailing Caverns, the Druids of the Fang, are an aberration. They were part of an order of noble druids whose plan was to heal the Barrens, but now seek to remake that land to match their own, twisted dreams."},
    [6505]={name="Crescent Staff",quality=3,ilvl=24,reqLevel=10,sourceType="quest_reward",instructions="Reward from the quest 'Leaders of the Fang'. Pick it over the other reward choices. Starts with Nara Wildmane in Thunder Bluff. Objective: Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff.",zone="Wailing Caverns",questName="Leaders of the Fang",lore="The druids in the Wailing Caverns, the Druids of the Fang, are an aberration. They were part of an order of noble druids whose plan was to heal the Barrens, but now seek to remake that land to match their own, twisted dreams."},
