    [11994]={name="Coral Band",quality=2,ilvl=25,reqLevel=20,sourceType="world_drop",instructions="World drop around level 20-26."},
    [12000]={name="Limb Cleaver",quality=2,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Hurley Blackbreath'. Pick it over the other reward choices. Starts with Ragnar Thunderbrew in Dun Morogh. Objective: Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos.",zone="Blackrock Depths",questName="Hurley Blackbreath",lore="The Dark Iron dwarves, led by the villain Hurley Blackbreath, stole one of the Thunderbrew's best recipes, Thunderbrew Lager. The villains! They don't deserve such a fine brew!, I have a tough task for you."},
    [12006]={name="Meadow Ring",quality=2,ilvl=22,reqLevel=17,sourceType="world_drop",instructions="World drop around level 17-24."},
    [12007]={name="Prairie Ring",quality=2,ilvl=25,reqLevel=20,sourceType="world_drop",instructions="World drop around level 20-26."},
    [12008]={name="Savannah Ring",quality=2,ilvl=28,reqLevel=23,sourceType="world_drop",instructions="World drop around level 23-29."},
    [12018]={name="Conservator Helm",quality=2,ilvl=54,sourceType="quest_reward",instructions="Reward from the quest 'Abandoned Hope'. Pick it over the other reward choices. Starts with Marshal Windsor in Burning Steppes. Objective: Give Marshal Maxwell the bad news.",zone="Blackrock Depths",questName="Abandoned Hope",lore="Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat. He is a blind buffoon. Proof stands two feet away from him and he does not see."},
    [12019]={name="Cerulean Talisman",quality=2,ilvl=32,reqLevel=27,sourceType="world_drop",instructions="World drop around level 26-33."},
