    [19831]={name="Zandalar Predator's Mantle",quality=4,ilvl=68,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Predator's Mantle'. Starts with Falthir the Sightless in Stranglethorn Vale. Objective: Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: A Primal Hakkari Aegis. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.Falthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.",zone="Zul'Gurub",questName="Paragons of Power: The Predator's Mantle",lore="We Zandalar prize what we wear as a symbol of accomplishment."},
    [19832]={name="Zandalar Predator's Belt",quality=4,ilvl=61,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Predator's Belt'. Starts with Falthir the Sightless in Stranglethorn Vale. Objective: Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: A Primal Hakkari Shawl. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.Falthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.",zone="Zul'Gurub",questName="Paragons of Power: The Predator's Belt",lore="You must master both to have any chance of success in Zul'Gurub... and any chance of being like the Zandalar predators."},
    [19833]={name="Zandalar Predator's Bracers",quality=4,ilvl=61,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Predator's Bracers'. Starts with Falthir the Sightless in Stranglethorn Vale. Objective: Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: A Primal Hakkari Bindings. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.Falthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.",zone="Zul'Gurub",questName="Paragons of Power: The Predator's Bracers",lore="In the dark times after the fall of the Gurubashi Empire, Zandalar predators used their prowess to provide sustenance for the tribe."},
    [19859]={name="Fang of the Faceless",quality=4,ilvl=68,reqLevel=60,sourceType="boss_drop",instructions="Drops from Hakkar.",zone="Zul'Gurub",npc="Hakkar",lore="The Soulflayer, a blood god the Atal'ai priests summoned into Zul'Gurub. He feeds on the blood of his own worshippers, which is the part they had not planned for."},
    [19874]={name="Halberd of Smiting",quality=4,ilvl=66,reqLevel=60,sourceType="boss_drop",instructions="Drops from Bloodlord Mandokir.",zone="Zul'Gurub",npc="Bloodlord Mandokir",proc="Equip: Chance to decapitate the target on a melee swing, causing 452 to 676 damage."},
    [19875]={name="Bloodstained Coif",quality=3,ilvl=71,reqLevel=60,sourceType="boss_drop",instructions="Drops from Jin'do the Hexxer.",zone="Zul'Gurub",npc="Jin'do the Hexxer",lore="Hakkar's chief hexxer, who fights by binding pieces of his enemies' spirits and setting them loose."},
