    [20577]={name="Nightmare Blade",quality=4,ilvl=71,reqLevel=60,sourceType="boss_drop",instructions="Drops from Taerar.",npc="Taerar",lore="A Nightmare-corrupted green dragon who splits himself into shades rather than face a fight whole."},
    [20599]={name="Polished Ironwood Crossbow",quality=4,ilvl=71,reqLevel=60,sourceType="boss_drop",instructions="Drops from Emeriss.",npc="Emeriss",lore="One of Ysera's four green consorts, corrupted by the Emerald Nightmare and now roaming Feralas, rotting the ground it stands on."},
